#[path = "solution.rs"]
mod solution;

use solution::{RegistryError, TagRegistry};

#[test]
fn empty_registry_and_disabled_batches_are_noops() {
    let mut registry = TagRegistry::new();
    assert!(registry.tags().is_empty());
    registry.register_batch(false, &[("", "bad-name"), ("unknown", "tag")]).unwrap();
    assert!(registry.tags().is_empty());
    registry.register_batch(true, &[]).unwrap();
    assert!(registry.tags().is_empty());
}

#[test]
fn valid_names_and_sorted_owned_tag_output() {
    let mut registry = TagRegistry::new();
    registry.register_scope("z_scope").unwrap();
    registry.register_scope("Alpha2").unwrap();
    registry.register_tag("z_scope", "_tag9").unwrap();
    registry.register_tag("Alpha2", "beta").unwrap();
    registry.register_tag("Alpha2", "Alpha").unwrap();
    assert_eq!(registry.tags(), vec!["Alpha2::Alpha", "Alpha2::beta", "z_scope::_tag9"]);

    let mut returned = registry.tags();
    returned[0].push_str("-changed");
    assert_eq!(registry.tags()[0], "Alpha2::Alpha");
}

#[test]
fn invalid_names_are_rejected_with_the_original_name() {
    let mut registry = TagRegistry::new();
    for name in ["", "9scope", "bad-name", "éclair", "has space"] {
        match registry.register_scope(name) {
            Err(RegistryError::InvalidName(found)) => assert_eq!(found, name),
            _ => panic!("expected InvalidName"),
        }
    }
    registry.register_scope("valid").unwrap();
    match registry.register_tag("valid", "") {
        Err(RegistryError::InvalidName(found)) => assert_eq!(found, ""),
        _ => panic!("expected InvalidName"),
    }
}

#[test]
fn unknown_scopes_and_duplicates_report_required_payloads() {
    let mut registry = TagRegistry::new();
    match registry.register_tag("missing", "tag") {
        Err(RegistryError::UnknownScope(scope)) => assert_eq!(scope, "missing"),
        _ => panic!("expected UnknownScope"),
    }

    registry.register_scope("scope").unwrap();
    match registry.register_scope("scope") {
        Err(RegistryError::Duplicate(name)) => assert_eq!(name, "scope"),
        _ => panic!("expected Duplicate"),
    }
    registry.register_tag("scope", "tag").unwrap();
    match registry.register_tag("scope", "tag") {
        Err(RegistryError::Duplicate(name)) => assert_eq!(name, "scope::tag"),
        _ => panic!("expected Duplicate"),
    }
}

#[test]
fn enabled_batch_is_atomic_and_processes_in_order() {
    let mut registry = TagRegistry::new();
    registry.register_scope("s").unwrap();
    registry.register_tag("s", "existing").unwrap();

    match registry.register_batch(true, &[("s", "first"), ("missing", "second")]) {
        Err(RegistryError::UnknownScope(scope)) => assert_eq!(scope, "missing"),
        _ => panic!("expected UnknownScope"),
    }
    assert_eq!(registry.tags(), vec!["s::existing"]);
    registry.register_tag("s", "first").unwrap();
}

#[test]
fn clone_has_independent_registry_state() {
    let mut original = TagRegistry::new();
    original.register_scope("s").unwrap();
    let mut cloned = original.clone();
    cloned.register_tag("s", "only_clone").unwrap();
    assert!(original.tags().is_empty());
    assert_eq!(cloned.tags(), vec!["s::only_clone"]);
}

